using System;using System.Linq;using System.Reflection;using NUnit.Framework;using Rootborn.Tests.EditMode.Dialogue;using Rootborn.UI.Objectives;using Rootborn.UI.Careers;using Rootborn.Game.Careers;using Rootborn.Game.Common;using Rootborn.Game.StudentLife;using Rootborn.Game.Localization;using UnityEngine;namespace Rootborn.Tests.EditMode.UI.Objectives{public sealed class StudentDayGuidePresentationTests{
private const string CatalogJson="{\"entries\": [{\"key\": \"ui.objectives.student_day_guide\", \"ko\": \"\\uc624\\ub298\\uc758 \\ud559\\uad50\\uc0dd\\ud65c\", \"en\": \"Student Day Guide\"}, {\"key\": \"ui.objectives.career_day_guide\", \"ko\": \"\\uc624\\ub298\\uc758 \\uc2dc\\uc124 \\uc6b4\\uc601\", \"en\": \"Career Day Guide\"}, {\"key\": \"ui.objectives.day_progress\", \"ko\": \"{0}\\uc77c | \\uccb4\\ub825 {1} | \\uc9d1\\uc911 {2}\", \"en\": \"Day {0} | Energy {1} | Focus {2}\"}, {\"key\": \"ui.objectives.finish_day_hint\", \"ko\": \"\\uc624\\ub298\\uc758 \\ud65c\\ub3d9\\uc744 \\ub9c8\\ucce4\\uc2b5\\ub2c8\\ub2e4. \\uc9d1\\uc5d0\\uc11c \\ud558\\ub8e8\\ub97c \\ub9c8\\ubb34\\ub9ac\\ud558\\uc138\\uc694.\", \"en\": \"Today's activities are complete. Return home to finish the day.\"}, {\"key\": \"ui.objectives.career_day_hint\", \"ko\": \"\\uc2dc\\uc124\\uc5d0\\uc11c \\uc5c5\\ubb34\\ub97c \\ud558\\uac70\\ub098 \\uc6b4\\uc601 \\uc0c1\\ud0dc\\uc640 \\ub2e4\\uc74c \\uc5c5\\uadf8\\ub808\\uc774\\ub4dc\\ub97c \\ud655\\uc778\\ud558\\uc138\\uc694.\", \"en\": \"Work at your facility or review its operations and next upgrade.\"}, {\"key\": \"ui.objectives.student_day_hint\", \"ko\": \"\\ub9c8\\uc744\\uc5d0\\uc11c \\ud65c\\ub3d9\\ud558\\uac70\\ub098 \\uc0ac\\ub78c\\ub4e4\\uacfc \\uc774\\uc57c\\uae30\\ud558\\uba70 \\ub2e4\\uc74c \\ubaa9\\ud45c\\ub97c \\ucc3e\\uc544\\ubcf4\\uc138\\uc694.\", \"en\": \"Choose a town activity or relationship action.\"}, {\"key\": \"ui.objectives.pending_activity_hint\", \"ko\": \"\\uba3c\\uc800 \\uc9c4\\ud589 \\uc911\\uc778 \\ud65c\\ub3d9\\uc744 \\ub9c8\\ubb34\\ub9ac\\ud558\\uc138\\uc694.\", \"en\": \"Finish the activity already in progress first.\"}, {\"key\": \"ui.tutorial.town_routine_hint\", \"ko\": \"\\ub9c8\\uc744\\uc758 \\uc0dd\\ud65c\\uc744 \\uc775\\ud788\\uace0 \\ud559\\uc0dd \\ud65c\\ub3d9\\uc744 \\ud558\\ub098 \\ub9c8\\uccd0 \\ubcf4\\uc138\\uc694.\", \"en\": \"Learn the town routine and finish one student activity.\"}, {\"key\": \"ui.tutorial.next_goal_hint\", \"ko\": \"\\uc548\\ub0b4\\uc778\\uacfc \\ub2e4\\uc2dc \\uc774\\uc57c\\uae30\\ud558\\uace0 \\ub2e4\\uc74c \\ubaa9\\ud45c\\ub97c \\uc120\\ud0dd\\ud558\\uc138\\uc694.\", \"en\": \"Talk to the guide again and choose your next goal.\"}]}";
NpcDialogueContextTests fixture;AdultCareerRuntimeComponent owner;GameDataRegistry registry;GameTextCatalog catalog;TutorialStageDefinition stage;string oldLanguage;
[SetUp]public void Setup(){oldLanguage=GameText.Language;GameText.Language="ko";fixture=new NpcDialogueContextTests();fixture.Setup();var flags=BindingFlags.Instance|BindingFlags.NonPublic;owner=(AdultCareerRuntimeComponent)typeof(NpcDialogueContextTests).GetField("_owner",flags).GetValue(fixture);registry=(GameDataRegistry)typeof(NpcDialogueContextTests).GetField("_registry",flags).GetValue(fixture);catalog=ScriptableObject.CreateInstance<GameTextCatalog>();catalog.ConfigureJson(CatalogJson);Assert.That(catalog.Get("ui.objectives.student_day_guide","ko").Any(c=>c>=0xAC00&&c<=0xD7A3),Is.True,"Korean fixture must survive UTF-8");typeof(GameDataRegistry).GetField("_textCatalog",flags).SetValue(registry,catalog);stage=ScriptableObject.CreateInstance<TutorialStageDefinition>();stage.ConfigureForTests("tutorial.fixture","Fixture","ui.tutorial.next_goal_hint");typeof(GameDataRegistry).GetField("_tutorialStages",flags).SetValue(registry,new[]{stage});var progress=owner.StudentComponent.Progress;progress.SetTutorialStage(stage,"goal.fixture");var data=progress.ToSaveData();data.CurrentDay=3;data.NextGuideText="OLD SAVED Day2 English tutorial";owner.StudentComponent.RestoreFromSaveData(data,Array.Empty<TraitDefinition>(),Array.Empty<SkillDefinition>(),Array.Empty<CareerDefinition>());}
[TearDown]public void Cleanup(){fixture?.Cleanup();if(catalog!=null)UnityEngine.Object.DestroyImmediate(catalog);if(stage!=null)UnityEngine.Object.DestroyImmediate(stage);GameText.Language=oldLanguage;}
ObjectiveJournalItem Build()=>new StudentDayGuideObjectiveSource().BuildItems(new ObjectiveJournalContext(registry,owner.gameObject,null)).Single();
void MakeAdult(bool pending=false){var data=new AdultCareerProgressSaveData{SaveSlot=owner.Progress.SaveSlot,PlayerId=owner.Progress.PlayerId,FacilityId="fixture.facility",FacilityLevel=1,PendingWork=pending?new PendingFacilityWorkSaveData{RequestId="pending",WorkId="fixture.work",MinigameId="fixture.game",Day=3,ReservedTimePoints=2,Seed=1,FacilityLevel=1,RewardPercent=100}:null};typeof(AdultCareerRuntimeComponent).GetProperty("Progress").SetValue(owner,AdultCareerProgress.FromSaveData(data));}
[Test]public void KoreanGuideUsesCurrentDayAndRegisteredStageRatherThanLegacySavedLiteral(){var progress=owner.StudentComponent.Progress;string before=JsonUtility.ToJson(progress.ToSaveData());var item=Build();Assert.That(item.Title,Is.EqualTo(catalog.Get("ui.objectives.student_day_guide","ko")));Assert.That(item.ProgressText,Does.StartWith("3"+(char)0xC77C+" | "));Assert.That(item.NextHintText,Is.EqualTo(catalog.Get("ui.tutorial.next_goal_hint","ko")));Assert.That(item.StableKey,Is.EqualTo("student-day.goal.fixture"));Assert.That(JsonUtility.ToJson(progress.ToSaveData()),Is.EqualTo(before),"Presentation must not rewrite tutorial or save progress");}
[Test]public void ExhaustedTimePromptsDayEndWithoutOfferingUnavailableActivities(){var p=owner.StudentComponent.Progress;Assert.That(p.TrySpendTimePoints(p.TimePointsRemaining),Is.True);Assert.That(Build().NextHintText,Is.EqualTo(catalog.Get("ui.objectives.finish_day_hint","ko")));Assert.That(p.NextObjectiveId,Is.EqualTo("goal.fixture"));}
[Test]public void AdultGuideUsesCareerPhaseWithoutStudentTutorial(){MakeAdult();var item=Build();Assert.That(item.Title,Is.EqualTo(catalog.Get("ui.objectives.career_day_guide","ko")));Assert.That(item.NextHintText,Is.EqualTo(catalog.Get("ui.objectives.career_day_hint","ko")));}
[Test]public void PendingAdultWorkTakesPriorityOverDayEndPrompt(){MakeAdult(true);var p=owner.StudentComponent.Progress;p.TrySpendTimePoints(p.TimePointsRemaining);Assert.That(owner.Progress.HasPendingWork,Is.True);Assert.That(Build().NextHintText,Is.EqualTo(catalog.Get("ui.objectives.pending_activity_hint","ko")));}
[Test]public void UnknownCustomGuideRemainsAvailableInEnglishFallback(){GameText.Language="en";typeof(GameDataRegistry).GetField("_tutorialStages",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(registry,Array.Empty<TutorialStageDefinition>());var item=Build();Assert.That(item.Title,Is.EqualTo("Student Day Guide"));Assert.That(item.NextHintText,Is.EqualTo("OLD SAVED Day2 English tutorial"));}
[Test]public void NoPlayerProducesNoGuide(){Assert.That(new StudentDayGuideObjectiveSource().BuildItems(new ObjectiveJournalContext(registry,null,null)),Is.Empty);}
}}